@js:
    java.toast("正在努力加载中，请稍后");
var sort = [];
var push = (title, url, type1, type2) => {
    sort.push({
        title: title,
        url: url,
        style: {
            layout_flexGrow: type1,
            layout_flexBasisPercent: type2
        }
    });
};
var sites = [{
        u: "http://www.greentxt.net/sort/",
        ti: "༺ˇ»`全部小说´«ˇ༻"
    },
    {
        u: "http://www.greentxt.net/quanben/sort/",
        ti: "༺ˇ»`全本小说´«ˇ༻"
    }];
for (var site of sites) {
    var o = org.jsoup.Jsoup.parse(java.ajax(site.u));
    var s = o.select('div.class>ul>li>a');
    var u1 = site.u + "/{{page}}/";
    push(site.ti, u1, "1", "1");
    for (var i = 0; i < s.size(); i++) {
        var urls = String(s[i].attr("href")).replace(/(.*)\/(\d+)\//,"$1/{{page}}/");
        if (i + 1 <= s.length - s.length % 3) {
            push(s[i].text(), urls, "1", "0.25")
        } else {
        push(s[i].text(), urls, "-1", "0.29")
        }
    }
}
JSON.stringify(sort);
